-- Shape sensitive operational records; never expose provider payloads or auth secrets.
create or replace function public.admin_customer_detail(target_customer uuid) returns jsonb language plpgsql stable security definer set search_path=public,auth as $$
declare result jsonb;begin if not public.admin_has_permission('customer_support')then raise exception 'Not authorised';end if;select jsonb_build_object('profile',jsonb_build_object('id',p.id,'full_name',p.full_name,'email',u.email,'phone',p.phone,'alternative_phone',p.alternative_phone,'account_type',p.role,'registered_at',p.created_at,'last_activity',coalesce(p.last_activity_at,u.last_sign_in_at),'account_status',p.account_status,'verification_status',p.verification_status),'addresses',(select coalesce(jsonb_agg(jsonb_build_object('label',a.label,'region',a.region,'city',a.city,'area',a.area,'digital_address',a.digital_address,'is_default',a.is_default)order by a.is_default desc),'[]')from addresses a where a.user_id=p.id),'orders',(select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'order_number',o.order_number,'status',o.status,'total',o.total,'created_at',o.created_at)order by o.created_at desc),'[]')from orders o where o.customer_id=p.id),'quotes',(select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'title',q.title,'status',q.status,'delivery_location',q.delivery_location,'created_at',q.created_at)order by q.created_at desc),'[]')from quote_requests q where q.requester_id=p.id),'projects',(select coalesce(jsonb_agg(jsonb_build_object('id',pr.id,'name',pr.name,'status',pr.status,'budget',pr.budget,'created_at',pr.created_at)order by pr.created_at desc),'[]')from projects pr where pr.owner_id=p.id),'payments',(select coalesce(jsonb_agg(jsonb_build_object('id',pay.id,'order_id',pay.order_id,'provider',pay.provider,'amount',pay.amount,'currency',pay.currency,'status',pay.status,'paid_at',pay.paid_at,'created_at',pay.created_at)order by pay.created_at desc),'[]')from payments pay join orders o on o.id=pay.order_id where o.customer_id=p.id),'deliveries',(select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'order_id',d.order_id,'status',d.status,'delivery_location',d.delivery_location,'delivered_at',d.delivered_at,'created_at',d.created_at)order by d.created_at desc),'[]')from deliveries d join orders o on o.id=d.order_id where o.customer_id=p.id),'disputes',(select coalesce(jsonb_agg(jsonb_build_object('id',di.id,'order_id',di.order_id,'reason',di.reason,'status',di.status,'resolution_notes',di.resolution_notes,'created_at',di.created_at)order by di.created_at desc),'[]')from order_disputes di where di.customer_id=p.id),'reviews',(select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'order_id',r.order_id,'rating',r.rating,'comment',r.comment,'created_at',r.created_at)order by r.created_at desc),'[]')from reviews r where r.reviewer_id=p.id),'memberships',(select coalesce(jsonb_agg(jsonb_build_object('organisation_id',om.organisation_id,'name',org.name,'role',om.member_role,'active',om.is_active)),'[]')from organisation_members om join organisations org on org.id=om.organisation_id where om.user_id=p.id),'financial',jsonb_build_object('total_spent',(select coalesce(sum(total),0)from orders where customer_id=p.id and status not in('cancelled')),'total_refunds',(select coalesce(sum(amount),0)from payments pay join orders o on o.id=pay.order_id where o.customer_id=p.id and pay.status='refunded'),'outstanding',(select coalesce(sum(total),0)from orders where customer_id=p.id and status='awaiting_payment'),'average_order_value',(select coalesce(avg(total),0)from orders where customer_id=p.id),'completed_orders',(select count(*)from orders where customer_id=p.id and status='completed'),'cancelled_orders',(select count(*)from orders where customer_id=p.id and status='cancelled')),'notes',(select coalesce(jsonb_agg(jsonb_build_object('note',n.note,'author_id',n.author_id,'created_at',n.created_at)order by n.created_at desc),'[]')from admin_internal_notes n where n.subject_type='customer'and n.subject_id=p.id),'actions',(select coalesce(jsonb_agg(jsonb_build_object('action',h.action,'reason',h.reason,'actor_id',h.actor_id,'created_at',h.created_at)order by h.created_at desc),'[]')from admin_action_history h where h.subject_type='customer'and h.subject_id=p.id))into result from profiles p join auth.users u on u.id=p.id where p.id=target_customer and p.role in('customer','contractor','professional');if result is null then raise exception 'Customer not found';end if;return result;end;$$;
